#pragma once

#include <cstddef>
#include <cstdint>
#include <vector>
#include <string>

namespace dsp {

/**
 * @brief Signal type generated by the simulated ADC.
 */
enum class WaveformType {
    Sine,              ///< Single tone pure sinusoidal waveform
    MultiTone,         ///< Sum of primary passband tone and high-frequency interference tone
    SineWithNoise,     ///< Sinusoid plus additive white pseudo-random noise
    Impulse,           ///< Discrete Dirac impulse (unit sample at index 0 or specified delay)
    Step,              ///< Discrete unit step function
    SquareWave,        ///< Periodic square wave for transient response
    CustomSequence     ///< Pre-loaded deterministic user sequence
};

/**
 * @brief Structure representing a single digitized ADC sample.
 * Clearly labeled as simulated ADC telemetry.
 */
struct SimulatedAdcSample {
    uint16_t raw_counts{0};       ///< Quantized integer counts (e.g., 0..4095 for 12-bit SAR ADC)
    float voltage{0.0f};          ///< Reconstructed analog voltage (0.0 to Vref)
    float normalized{0.0f};       ///< AC-coupled / normalized DSP input in [-1.0, +1.0] range
    uint64_t sample_index{0};     ///< Monotonic sequence number
    static constexpr bool is_simulated_adc_data = true; ///< Explicit indicator that data is synthetic
};

/**
 * @brief Configuration parameters for simulated ADC source.
 */
struct SimulatedAdcConfig {
    float sample_rate_hz{10000.0f};   ///< ADC sampling frequency (Fs)
    uint8_t bit_depth{12};            ///< ADC resolution (typical STM32 ADC = 12 bits)
    float v_ref{3.3f};                ///< ADC reference voltage (3.3V)
    WaveformType waveform{WaveformType::MultiTone};
    float primary_freq_hz{250.0f};    ///< Desired passband signal frequency (e.g. 250 Hz)
    float primary_amplitude{0.7f};    ///< Amplitude relative to full-scale
    float secondary_freq_hz{2500.0f}; ///< Interference stopband frequency (e.g. 2500 Hz)
    float secondary_amplitude{0.3f};  ///< Interference amplitude
    float noise_variance{0.005f};     ///< Additive noise variance (0 = clean)
    uint32_t random_seed{1337};       ///< Fixed seed for 100% deterministic reproducibility
    bool enable_quantization{true};   ///< Apply 12-bit discrete quantization
};

/**
 * @brief Abstract interface for an ADC source.
 *
 * This clean abstraction enables desktop firmware simulation today and allows
 * seamless drop-in replacement with STM32 ADC+DMA interrupt-driven drivers tomorrow.
 */
class IAdcSource {
public:
    virtual ~IAdcSource() = default;

    /**
     * @brief Acquires the next single sample.
     */
    virtual SimulatedAdcSample acquire_sample() noexcept = 0;

    /**
     * @brief Acquires a block of normalized floating-point samples.
     * @param out_buffer Output buffer to fill.
     * @param count Number of samples requested.
     * @return Number of samples actually acquired.
     */
    virtual std::size_t acquire_block(float* out_buffer, std::size_t count) noexcept = 0;

    /**
     * @brief Returns active sampling rate in Hz.
     */
    virtual float sample_rate_hz() const noexcept = 0;

    /**
     * @brief Resets generator state and phase counters.
     */
    virtual void reset() noexcept = 0;
};

/**
 * @brief Deterministic simulated ADC implementation.
 *
 * Models a SAR ADC with configurable bit-depth, Vref, deterministic synthetic signals,
 * and ADC quantization noise. All samples are explicitly marked as simulated data.
 */
class SimulatedAdc : public IAdcSource {
public:
    explicit SimulatedAdc(const SimulatedAdcConfig& config = SimulatedAdcConfig{});

    SimulatedAdcSample acquire_sample() noexcept override;
    std::size_t acquire_block(float* out_buffer, std::size_t count) noexcept override;
    float sample_rate_hz() const noexcept override { return config_.sample_rate_hz; }
    void reset() noexcept override;

    void set_custom_sequence(const std::vector<float>& sequence);
    const SimulatedAdcConfig& config() const noexcept { return config_; }

    /**
     * @brief Quantizes a continuous analog voltage into discrete ADC integer counts.
     */
    uint16_t quantize_voltage(float v) const noexcept;

private:
    float compute_analog_voltage(uint64_t n) noexcept;
    float generate_pseudo_noise() noexcept;

    SimulatedAdcConfig config_;
    uint64_t sample_counter_{0};
    uint32_t lcg_state_{1337};
    std::vector<float> custom_sequence_;
    std::size_t custom_index_{0};
    uint32_t max_counts_{4095};
};

} // namespace dsp
